$ErrorActionPreference = "Stop"

$ProjectRoot = (Get-Location).Path
$PackagePath = Join-Path $ProjectRoot "package.json"
$P03Path = Join-Path $ProjectRoot ".private\entity\build\P03\evidence-packets.json"
$CompilerPath = Join-Path $ProjectRoot "scripts\entity\build-cached-emet-explanations.js"
$BatchPath = Join-Path $ProjectRoot "scripts\entity\batch-cached-emet-explanations.js"
$SchedulerPath = Join-Path $ProjectRoot "scripts\entity\schedule-cached-emet-generation.js"
$PromptPath = Join-Path $ProjectRoot "scripts\entity\emet-prompts\emet-free-tier-v1.js"
$TestPath = Join-Path $ProjectRoot "scripts\entity\test-emet-reader-explanation.js"
$NotesPath = Join-Path $ProjectRoot "P04_READER_FIRST_PRODUCTION_NOTES.md"
$SchedulerStatePath = Join-Path $ProjectRoot ".private\entity\build\P04\scheduler-state.json"
$EnvPath = Join-Path $ProjectRoot ".env.local"
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot ".private\entity\backups\P04-reader-first-v1.5.1-$Timestamp"

$CompilerPayload = ""
$BatchPayload = ""
$SchedulerPayload = ""
$PromptPayload = ""
$TestPayload = ""
$NotesPayload = ""

$InstalledPaths = @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath, $NotesPath)

function Write-Payload {
    param([Parameter(Mandatory)][string]$Payload, [Parameter(Mandatory)][string]$Path)
    $directory = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $directory | Out-Null
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Payload))
}

function Backup-File {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path $Path)) { return }
    $relative = $Path.Substring($ProjectRoot.Length).TrimStart('\', '/')
    $destination = Join-Path $BackupRoot $relative
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $destination) | Out-Null
    Copy-Item -Force $Path $destination
}

function Restore-Backup {
    foreach ($path in $InstalledPaths) {
        $relative = $path.Substring($ProjectRoot.Length).TrimStart('\', '/')
        $backup = Join-Path $BackupRoot $relative
        if (Test-Path $backup) {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null
            Copy-Item -Force $backup $path
        } elseif (Test-Path $path) {
            Remove-Item -Force $path
        }
    }
    foreach ($path in @($PackagePath, $SchedulerStatePath, $EnvPath)) {
        $relative = $path.Substring($ProjectRoot.Length).TrimStart('\', '/')
        $backup = Join-Path $BackupRoot $relative
        if (Test-Path $backup) {
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $path) | Out-Null
            Copy-Item -Force $backup $path
        }
    }
}

function Set-PackageScripts {
    $tempScript = Join-Path $ProjectRoot ".private\entity\update-p04-v15-package.js"
    New-Item -ItemType Directory -Force -Path (Split-Path -Parent $tempScript) | Out-Null
    @'
const fs = require("fs");
const file = "package.json";
const raw = fs.readFileSync(file, "utf8").replace(/^\uFEFF/, "");
const pkg = JSON.parse(raw);
pkg.scripts = pkg.scripts || {};
Object.assign(pkg.scripts, {
  "build:cached-emet": "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js",
  "verify:cached-emet": "node --max-old-space-size=4096 scripts/entity/build-cached-emet-explanations.js --verify",
  "prepare:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --prepare",
  "submit:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --submit",
  "status:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --status",
  "import:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --import",
  "verify:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --verify",
  "cancel:cached-emet-batch": "node --max-old-space-size=4096 scripts/entity/batch-cached-emet-explanations.js --cancel",
  "emet:generate": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run",
  "emet:generate:plan": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --plan",
  "emet:generate:status": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --status",
  "emet:generate:watch": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --run --watch",
  "emet:generate:reset": "node --max-old-space-size=4096 scripts/entity/schedule-cached-emet-generation.js --reset",
  "test:emet-reader": "node --max-old-space-size=4096 scripts/entity/test-emet-reader-explanation.js"
});
fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + "\n", "utf8");
'@ | Set-Content -Path $tempScript -Encoding UTF8
    & node $tempScript
    if ($LASTEXITCODE -ne 0) { throw "Unable to update package.json." }
    Remove-Item -Force $tempScript
}

function Add-EnvDefault {
    param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][string]$Value)
    if (-not (Test-Path $EnvPath)) {
        [System.IO.File]::WriteAllText($EnvPath, "", (New-Object System.Text.UTF8Encoding($false)))
    }
    $content = Get-Content $EnvPath -Raw
    if ($null -eq $content) { $content = "" }
    if ($content -notmatch "(?m)^\s*$([regex]::Escape($Name))\s*=") {
        if ($content.Length -gt 0 -and -not $content.EndsWith("`n")) { $content += "`r`n" }
        $content += "$Name=$Value`r`n"
        [System.IO.File]::WriteAllText((Resolve-Path $EnvPath), $content, (New-Object System.Text.UTF8Encoding($false)))
    }
}

if (-not (Test-Path $PackagePath)) { throw "Run this installer from the ai-bible-app project root. package.json was not found." }
if (-not (Test-Path $P03Path)) { throw "P03 evidence-packets.json was not found. Complete P03 first." }

New-Item -ItemType Directory -Force -Path $BackupRoot | Out-Null
foreach ($path in @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath, $NotesPath, $PackagePath, $SchedulerStatePath, $EnvPath)) {
    Backup-File $path
}

$ActiveJobId = $null
if (Test-Path $SchedulerStatePath) {
    try {
        $schedulerState = Get-Content $SchedulerStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
        $ActiveJobId = $schedulerState.activeJobId
    } catch {
        Write-Warning "Could not read the existing scheduler state; it will be preserved in the backup."
    }
}

try {
    if ($ActiveJobId -and (Test-Path $BatchPath)) {
        Write-Host "Refreshing obsolete Batch job $ActiveJobId before changing the prompt..." -ForegroundColor Yellow
        & node --max-old-space-size=4096 $BatchPath --status --job $ActiveJobId
        if ($LASTEXITCODE -eq 0) {
            Write-Host "Cancelling the obsolete Batch job only if it is still active..." -ForegroundColor Yellow
            & node --max-old-space-size=4096 $BatchPath --cancel --job $ActiveJobId
            if ($LASTEXITCODE -ne 0) {
                Write-Warning "The obsolete Batch job could not be cancelled automatically. It will still be marked superseded and will not be imported under the new prompt."
            }
        } else {
            Write-Warning "The obsolete Batch status could not be refreshed. It will be marked superseded and will not be imported under the new prompt."
        }
    }

    Write-Host "Installing P04 reader-first production compiler v1.5.1..." -ForegroundColor Cyan
    Write-Payload $CompilerPayload $CompilerPath
    Write-Payload $BatchPayload $BatchPath
    Write-Payload $SchedulerPayload $SchedulerPath
    Write-Payload $PromptPayload $PromptPath
    Write-Payload $TestPayload $TestPath
    Write-Payload $NotesPayload $NotesPath
    Set-PackageScripts

    Add-EnvDefault "EMET_P04_BATCH_QUEUE_LIMIT" "5000000"
    Add-EnvDefault "EMET_P04_SCHEDULER_INPUT_TOKEN_BUDGET" "4500000"
    Add-EnvDefault "EMET_P04_SCHEDULER_REQUEST_SIZE" "1"
    Add-EnvDefault "EMET_P04_SCHEDULER_COOLDOWN_HOURS" "0"
    Add-EnvDefault "EMET_P04_OUTPUT_TOKEN_RESERVE" "600"
    Add-EnvDefault "EMET_P04_SCHEDULER_POLL_SECONDS" "60"

    if (Test-Path $SchedulerStatePath) {
        $state = Get-Content $SchedulerStatePath -Raw -Encoding UTF8 | ConvertFrom-Json
        if (-not $state.history) { $state | Add-Member -NotePropertyName history -NotePropertyValue @() -Force }
        if ($ActiveJobId) {
            $historyItem = [pscustomobject]@{
                at = (Get-Date).ToUniversalTime().ToString("o")
                action = "superseded-reader-first-prompt"
                jobId = $ActiveJobId
                newPromptVersion = "1.3.0"
            }
            $state.history = @($state.history) + $historyItem
        }
        $state.activeJobId = $null
        $state.nextEligibleSubmitAt = $null
        $state.updatedAt = (Get-Date).ToUniversalTime().ToString("o")
        $json = $state | ConvertTo-Json -Depth 100
        [System.IO.File]::WriteAllText((Resolve-Path $SchedulerStatePath), $json + "`r`n", (New-Object System.Text.UTF8Encoding($false)))
    }

    foreach ($path in @($CompilerPath, $BatchPath, $SchedulerPath, $PromptPath, $TestPath)) {
        & node --check $path
        if ($LASTEXITCODE -ne 0) { throw "Syntax validation failed: $path" }
    }

    Write-Host "`nInspecting the new generation plan..." -ForegroundColor Cyan
    & npm run build:cached-emet -- --plan
    if ($LASTEXITCODE -ne 0) { throw "The P04 plan command failed after installation." }

    Write-Host "`nP04 reader-first production compiler v1.5.1 installed successfully." -ForegroundColor Green
    Write-Host "Backup: $BackupRoot"
    Write-Host "`nNext command:"
    Write-Host "npm run test:emet-reader -- --entity word:hebrew:H1077" -ForegroundColor Yellow
    Write-Host "`nDo not restart emet:generate:watch until that production-format test is approved."
} catch {
    Write-Warning "Installation failed. Restoring the previous files..."
    Restore-Backup
    throw
}
